const errorData = $input.item.json.execution.error || {};
const workflow = $input.item.json.workflow || {};
const execution = $input.item.json.execution || {};

const workflowName = workflow.name || 'Nova Workflow';
const workflowId = workflow.id || 'unknown';
const executionId = execution.id || 'unknown';
const nodeName = errorData.node ? errorData.node.name : 'Unknown Node';
const errorMessage = errorData.message || errorData.description || 'Execution failure';
const stackTrace = errorData.stack || JSON.stringify(errorData, null, 2);

return {
  json: {
    workflow_name: workflowName,
    workflow_id: workflowId,
    execution_id: executionId,
    node_name: nodeName,
    error_message: errorMessage,
    stack_trace: stackTrace,
    timestamp: new Date().toISOString()
  }
};

parameters.jsonBody:
={{ JSON.stringify({
  system_instruction: {
    parts: [{
      text: "You are Nova's Cloud AI Self-Healing Diagnostic Agent. Analyze n8n workflow execution errors and provide: 1) A concise 1-sentence root cause explanation for the user, and 2) A clear recommended fix strategy. Keep your diagnosis professional, clear, and actionable."
    }]
  },
  contents: [{
    parts: [{
      text: "Workflow Name: " + $json.workflow_name + "\nFailed Node: " + $json.node_name + "\nError Message: " + $json.error_message + "\nStack Trace: " + $json.stack_trace
    }]
  }],
  generationConfig: {
    temperature: 0.2
  }
}) }}

parameters.jsCode:
const diag = $input.item.json.candidates[0].content.parts[0].text;
const ctx = $('Prepare Diagnostic Payload').item.json;
const webhookUrl = process.env.N8N_HOST || 'https://automation.lesterlabs.cloud';

const slackBlocks = [
  {
    "type": "header",
    "text": {
      "type": "plain_text",
      "text": "🚨 Nova Cloud Workflow Failure Alert",
      "emoji": true
    }
  },
  {
    "type": "section",
    "fields": [
      { "type": "mrkdwn", "text": `*Workflow:*\n${ctx.workflow_name}` },
      { "type": "mrkdwn", "text": `*Failed Node:*\n${ctx.node_name}` },
      { "type": "mrkdwn", "text": `*Execution ID:*\n#${ctx.execution_id}` },
      { "type": "mrkdwn", "text": `*Timestamp:*\n${ctx.timestamp}` }
    ]
  },
  {
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": `*🤖 AI Diagnostic & Proposed Fix:*\n${diag}`
    }
  },
  {
    "type": "actions",
    "elements": [
      {
        "type": "button",
        "text": { "type": "plain_text", "text": "✅ Approve & Auto-Deploy Fix", "emoji": true },
        "style": "primary",
        "value": JSON.stringify({ action: "approve", workflow_id: ctx.workflow_id, execution_id: ctx.execution_id })
      },
      {
        "type": "button",
        "text": { "type": "plain_text", "text": "🔍 View Execution Logs", "emoji": true },
        "url": `${webhookUrl}/execution/${ctx.execution_id}`
      }
    ]
  }
];

return {
  json: {
    blocks: slackBlocks,
    text: `🚨 Nova Failure Alert: ${ctx.workflow_name} - ${ctx.node_name}`
  }
};

const payload = $input.item.json.body || {};
let actionData = {};
try {
  actionData = typeof payload.value === 'string' ? JSON.parse(payload.value) : (payload.value || {});
} catch(e) {
  actionData = {};
}

return {
  json: {
    action: actionData.action || 'approve',
    workflow_id: actionData.workflow_id || 'YRwbtSO1NMKf8Lev',
    execution_id: actionData.execution_id || 'unknown',
    timestamp: new Date().toISOString()
  }
};

parameters.responseBody:
={{ JSON.stringify({
  text: "✅ Fix approved! Nova AI Agent has re-activated the workflow live on n8n."
}) }}
